"// lib/widgets/admin_zone_tile.dart\nimport 'package:flutter/material.dart';\n\nclass AdminZoneTile extends StatelessWidget {\n  final Map<String, dynamic> zone;\n\n  const AdminZoneTile({Key? key, required this.zone}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    final String id = zone['id'] ?? 'unknown';\n    final double latitude = (zone['latitude'] ?? 0).toDouble();\n    final double longitude = (zone['longitude'] ?? 0).toDouble();\n    final double radius = (zone['radius'] ?? 0).toDouble();\n    final double confidence = (zone['confidence'] ?? 0).toDouble();\n\n    return Card(\n      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),\n      elevation: 4,\n      margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),\n      child: Container(\n        decoration: BoxDecoration(\n          gradient: LinearGradient(\n            colors: [Colors.purple.shade200, Colors.pinkAccent.shade100],\n            begin: Alignment.topLeft,\n            end: Alignment.bottomRight,\n          ),\n          borderRadius: BorderRadius.circular(16),\n        ),\n        padding: const EdgeInsets.all(16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Text('Zone ID: $id', style: const TextStyle(fontWeight: FontWeight.bold, color: Colors.white)),\n            const SizedBox(height: 4),\n            Text('Location: ${latitude.toStringAsFixed(4)}, ${longitude.toStringAsFixed(4)}', style: const TextStyle(color: Colors.white70)),\n            Text('Radius: ${radius.toStringAsFixed(1)} m', style: const TextStyle(color: Colors.white70)),\n            Text('Confidence: ${(confidence * 100).toStringAsFixed(0)}%', style: const TextStyle(color: Colors.white70)),\n          ],\n        ),\n      ),\n    );\n  }\n}\n"